sys_script.script:
(function executeRule(current, previous) {

    // Create Claim Notification record
    var notification = new GlideRecord(
        "x_snc_insurance_0_claim_notification"
    );

    notification.initialize();

    // Set the Claim reference directly
    notification.setValue(
        "claim",
        current.getUniqueValue()
    );

    // Set logged-in user
    notification.setValue(
        "user",
        gs.getUserID()
    );

    // Get Claim Number
    var claimNumber = current.getValue("claim_number");

    if (!claimNumber) {
        claimNumber = "your new claim";
    }

    // Set notification message
    notification.setValue(
        "message",
        "Your claim " +
        claimNumber +
        " has been submitted successfully."
    );

    // Set Notification Type
    notification.setValue(
        "notification_type",
        "claim_submitted"
    );

    // Mark as unread
    notification.setValue(
        "read",
        false
    );

    // Insert notification
    var notificationSysId = notification.insert();

    if (!notificationSysId) {

        gs.error(
            "Create Claim Submitted Notification: " +
            "Unable to create notification."
        );

    }

})(current, previous);
